import os
import re
from datetime import date

from fastapi import APIRouter, Depends, FastAPI, Header, HTTPException, Query, Response
from pydantic import AwareDatetime, BaseModel, Field

from pulso import correo, db, reloj

router = APIRouter()


def socio_actual(authorization: str | None = Header(default=None)):
    if not authorization or not authorization.startswith('Bearer '):
        raise HTTPException(401, 'Falta el token')
    socio = db.socio_por_token(authorization.removeprefix('Bearer '))
    if socio is None:
        raise HTTPException(401, 'Token inválido')
    return socio


def admin(x_admin_key: str | None = Header(default=None)):
    if not x_admin_key or x_admin_key != os.environ.get('PULSO_ADMIN_KEY'):
        raise HTTPException(401, 'Clave de administración inválida')


def ver_clase(clase):
    return dict(clase, lugares_libres=clase['cupo'] - db.confirmadas(clase['id']))


def ver_reserva(reserva):
    return {k: reserva[k] for k in ('id', 'clase_id', 'estado', 'creada')}


def parsear_dia(texto, nombre):
    if texto is None:
        return None
    try:
        if not re.fullmatch(r'\d{4}-\d{2}-\d{2}', texto):
            raise ValueError
        return date.fromisoformat(texto)
    except ValueError:
        raise HTTPException(422, f'{nombre} debe tener el formato YYYY-MM-DD')


@router.get('/clases')
def listar_clases(response: Response, desde: str | None = None, hasta: str | None = None,
                  instructor: str | None = None, con_lugar: bool = False,
                  pagina: int = Query(1, ge=1), por_pagina: int = Query(20, ge=1, le=50)):
    dia_desde = parsear_dia(desde, 'desde')
    dia_hasta = parsear_dia(hasta, 'hasta')
    if dia_desde and dia_hasta and dia_desde > dia_hasta:
        raise HTTPException(422, 'desde no puede ser posterior a hasta')
    ahora = reloj.ahora()
    resultado = []
    for c in db.clases():
        inicio = db.a_fecha(c['inicio'])
        if inicio <= ahora:
            continue
        dia = inicio.astimezone(reloj.MONTEVIDEO).date()
        if (dia_desde and dia < dia_desde) or (dia_hasta and dia > dia_hasta):
            continue
        if instructor is not None and c['instructor'].casefold() != instructor.casefold():
            continue
        resultado.append(c)
    if con_lugar:
        resultado = [v for v in map(ver_clase, resultado) if v['lugares_libres'] > 0]
    else:
        resultado = None if False else resultado
    total = len(resultado)
    response.headers['X-Total'] = str(total)
    inicio_pag = (pagina - 1) * por_pagina
    return [c if 'lugares_libres' in c else ver_clase(c)
            for c in resultado[inicio_pag:inicio_pag + por_pagina]]


@router.get('/clases/{clase_id}')
def obtener_clase(clase_id: int):
    clase = db.clase(clase_id)
    if clase is None:
        raise HTTPException(404, 'No existe la clase')
    return ver_clase(clase)


